--- a/src/main/java/com/pulsestream/telemetry/ingestion/infrastructure/DeviceCredentialAuthenticationManager.java
+++ b/src/main/java/com/pulsestream/telemetry/ingestion/infrastructure/DeviceCredentialAuthenticationManager.java
@@ -5,6 +5,7 @@
 import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
 import org.springframework.security.core.Authentication;
 import org.springframework.security.core.userdetails.ReactiveUserDetailsService;
+import org.springframework.security.core.userdetails.UserDetails;
 import org.springframework.security.crypto.password.PasswordEncoder;
 import reactor.core.publisher.Mono;

@@ -19,12 +20,26 @@
         this.encoder = Objects.requireNonNull(encoder, "encoder");
     }

+    @Override
     public Mono<Authentication> authenticate(Authentication authentication) {
-        Object name = authentication.getPrincipal();
-        Object secret = authentication.getCredentials();
-        if (name == null || secret == null) {
+        Object principal = authentication.getPrincipal();
+        Object credentials = authentication.getCredentials();
+        if (principal == null || credentials == null) {
             return Mono.empty();
         }
-        return users.findByUsername(name.toString()).filter(user -> user.isEnabled() && user.isAccountNonLocked() && user.isAccountNonExpired() && user.isCredentialsNonExpired()).filter(user -> encoder.matches(secret.toString(), user.getPassword())).<Authentication>map(user -> UsernamePasswordAuthenticationToken.authenticated(user.getUsername(), null, user.getAuthorities())).onErrorResume(error -> Mono.empty());
+        String rawSecret = credentials.toString();
+        return users.findByUsername(principal.toString())
+                .filter(DeviceCredentialAuthenticationManager::isUsable)
+                .filter(user -> encoder.matches(rawSecret, user.getPassword()))
+                .<Authentication>map(DeviceCredentialAuthenticationManager::toAuthenticated)
+                .onErrorResume(error -> Mono.empty());
+    }
+
+    private static boolean isUsable(UserDetails user) {
+        return user.isEnabled() && user.isAccountNonLocked() && user.isAccountNonExpired() && user.isCredentialsNonExpired();
+    }
+
+    private static Authentication toAuthenticated(UserDetails user) {
+        return UsernamePasswordAuthenticationToken.authenticated(user.getUsername(), null, user.getAuthorities());
     }
 }
